namespace sv_8fc424bd8ca54dd8ba8c4763a0467937.Services;

/// <summary>
/// Scoped service (one per circuit) that tracks low-stock alert counts.
/// Components subscribe to <see cref="OnChange"/> to be notified when
/// new data arrives, regardless of which component triggered the poll.
/// </summary>
public sealed class InventoryAlertService
{
    private static readonly Random s_random = new();

    public int CurrentAlertCount { get; private set; }

    public event Action? OnChange;

    /// <summary>
    /// Simulates a database query that returns the number of items
    /// below minimum stock levels for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate latency + random result (0–15)
        var count = s_random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Updates the cached alert count and notifies ALL subscribers.
    /// Called by whichever component is polling; every other subscriber
    /// re-renders automatically.
    /// </summary>
    public void UpdateAlertCount(int count)
    {
        CurrentAlertCount = count;
        OnChange?.Invoke();
    }
}

