@using sv_8fc424bd8ca54dd8ba8c4763a0467937.Services
@rendermode InteractiveServer
@inject CascadingValueSource<WarehouseInfo> WarehouseSource

<select class="form-select form-select-sm" style="width:auto"
        value="@Warehouse?.SelectedWarehouseId"
        @onchange="OnWarehouseChanged">
    @foreach (var (id, name) in WarehouseInfo.AvailableWarehouses)
    {
        <option value="@id">@name</option>
    }
</select>

@code {
    [CascadingParameter]
    private WarehouseInfo? Warehouse { get; set; }

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        if (Warehouse is not null)
        {
            Warehouse.SelectedWarehouseId = e.Value?.ToString() ?? "WH-1";
            await WarehouseSource.NotifyChangedAsync(Warehouse);
        }
    }
}

@using sv_8fc424bd8ca54dd8ba8c4763a0467937.Services
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable

<span class="badge rounded-pill @BadgeClass">@AlertService.CurrentAlertCount</span>

@code {
    private Action? _handler;

    private string BadgeClass => AlertService.CurrentAlertCount switch
    {
        > 10 => "bg-danger",
        > 5  => "bg-warning text-dark",
        > 0  => "bg-info",
        _    => "bg-secondary"
    };

    protected override void OnInitialized()
    {
        // Wrap in InvokeAsync because the event may fire from a timer callback
        // on a different component's context.
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
    }
}

@page "/dashboard"
@using sv_8fc424bd8ca54dd8ba8c4763a0467937.Services
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4" style="max-width: 30rem;">
    <div class="card-body">
        <h5 class="card-title">
            Current Warehouse:
            <strong>@(WarehouseInfo.AvailableWarehouses
                        .FirstOrDefault(w => w.Id == Warehouse?.SelectedWarehouseId).Name
                     ?? "Unknown")</strong>
        </h5>
        <p class="card-text">
            Low-stock alerts: <AlertBadge />
        </p>
        <p class="text-muted small mb-0">
            Polling every 10 seconds. Last checked: @_lastChecked?.ToString("T")
        </p>
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseInfo? Warehouse { get; set; }

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private DateTime? _lastChecked;
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Initial fetch, then start the 10-second polling loop.
            await FetchAlertCountAsync();
            _ = PollLoopAsync();
        }
    }

    private async Task PollLoopAsync()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        try
        {
            while (await _timer.WaitForNextTickAsync(_cts.Token))
            {
                await FetchAlertCountAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Normal shutdown when the component disposes.
        }
    }

    private async Task FetchAlertCountAsync()
    {
        var warehouseId = Warehouse?.SelectedWarehouseId ?? "WH-1";
        var count = await AlertService.GetLowStockCountAsync(warehouseId);

        // Pushes the new count into the service and fires OnChange,
        // which re-renders every subscribed component (sidebar badge, etc.).
        AlertService.UpdateAlertCount(count);

        _lastChecked = DateTime.Now;
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

